#include <string>
#include <vector>
#include <algorithm>

class Solution {
public:
    std::string processString(std::string s, std::vector<std::vector<int>>& queries) {
        for (const auto& q : queries) {
            int t = q[0], l = q[1], r = q[2];
            if (t == 1) {
                std::reverse(s.begin() + l, s.begin() + r + 1);
            } else if (t == 2) {
                std::rotate(s.begin() + l, s.begin() + r, s.begin() + r + 1);
            }
        }
        return s;
    }
};

class Solution {
    public String processString(String s, int[][] queries) {
        char[] arr = s.toCharArray();
        for (int[] q : queries) {
            int t = q[0], l = q[1], r = q[2];
            if (t == 1) {
                int left = l, right = r;
                while (left < right) {
                    char tmp = arr[left];
                    arr[left] = arr[right];
                    arr[right] = tmp;
                    left++;
                    right--;
                }
            } else if (t == 2) {
                char last = arr[r];
                for (int i = r; i > l; i--) {
                    arr[i] = arr[i - 1];
                }
                arr[l] = last;
            }
        }
        return new String(arr);
    }
}

