var processString = function(s, queries) {
    const arr = s.split("");
    for (const [t, l, r] of queries) {
        if (t === 1) {
            let left = l, right = r;
            while (left < right) {
                const tmp = arr[left];
                arr[left] = arr[right];
                arr[right] = tmp;
                left++;
                right--;
            }
        } else if (t === 2) {
            const last = arr[r];
            for (let i = r; i > l; i--) {
                arr[i] = arr[i - 1];
            }
            arr[l] = last;
        }
    }
    return arr.join("");
};
